using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;
using Framework.Tilemap;
using Game.Map;
using Game.Stage;

namespace Game.Tests
{
    /// <summary>
    /// ゲーム専用ステージの生成処理と
    /// Tilemap描画を確認するテストクラス。
    /// </summary>
    public class MazeStageGeneratorTest : MonoBehaviour
    {
        #region Inspector Fields

        [Header("ステージ生成設定")]

        /// <summary>
        /// テスト用のステージ生成設定。
        /// </summary>
        [SerializeField]
        private MazeStageGenerationSettings settings =
            new MazeStageGenerationSettings();

        [Header("座標変換設定")]

        /// <summary>
        /// グリッド座標とワールド座標の変換システム。
        /// </summary>
        [SerializeField]
        [Tooltip("Gridに設定された座標変換コンポーネント")]
        private GridCoordinateConverter coordinateConverter;

        [Header("Tilemap設定")]

        /// <summary>
        /// 床の描画先Tilemap。
        /// </summary>
        [SerializeField]
        private Tilemap floorTilemap;

        /// <summary>
        /// 壁の描画先Tilemap。
        /// </summary>
        [SerializeField]
        private Tilemap wallTilemap;

        [Header("タイル設定")]

        /// <summary>
        /// 床の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase floorTile;

        /// <summary>
        /// 通常の壁の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase wallTile;

        /// <summary>
        /// 破壊可能な壁の描画に使用するタイル。
        /// 未設定の場合は通常の壁タイルを使用する。
        /// </summary>
        [SerializeField]
        private TileBase breakableWallTile;

        [Header("テスト設定")]

        /// <summary>
        /// 再生開始時にステージを生成するかどうか。
        /// </summary>
        [SerializeField]
        private bool generateOnStart = true;

        /// <summary>
        /// ステージ生成時に検証テストを実行するかどうか。
        /// </summary>
        [SerializeField]
        private bool runValidationTests = true;

        /// <summary>
        /// 生成したマップをConsoleへ出力するかどうか。
        /// </summary>
        [SerializeField]
        private bool printMap = true;

        [Header("Gizmos設定")]

        /// <summary>
        /// 配置地点をSceneビューに表示するかどうか。
        /// </summary>
        [SerializeField]
        private bool showGizmos = true;

        /// <summary>
        /// Gizmosの基本表示サイズ。
        /// </summary>
        [SerializeField]
        [Min(0.01f)]
        private float gizmoSize = 0.15f;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// 現在のステージ生成結果。
        /// </summary>
        private MazeStageGenerationResult result;

        /// <summary>
        /// マップのTilemap描画システム。
        /// </summary>
        private GridTilemapRenderer<MazeCell> renderer;

        /// <summary>
        /// 成功したテスト項目数。
        /// </summary>
        private int passedCount;

        /// <summary>
        /// 失敗したテスト項目数。
        /// </summary>
        private int failedCount;

        #endregion

        #region Unity Methods

        /// <summary>
        /// 再生開始時の処理。
        /// </summary>
        private void Start()
        {
            if (generateOnStart)
            {
                GenerateStage();
            }
        }

        /// <summary>
        /// オブジェクト破棄時に描画システムを解放する。
        /// </summary>
        private void OnDestroy()
        {
            ReleaseRenderer();
        }

        /// <summary>
        /// ステージ内の配置情報をGizmosで描画する。
        /// </summary>
        private void OnDrawGizmos()
        {
            if (!showGizmos ||
                result == null ||
                coordinateConverter == null)
            {
                return;
            }

            foreach (Vector2Int position
                     in result.Map.GetPositions())
            {
                MazeCell cell =
                    result.Map.GetCell(position);

                Vector3 worldPosition =
                    coordinateConverter.GetCellCenterWorld(
                        position);

                // Tilemapより手前に表示する。
                worldPosition.z -= 0.1f;

                // プレイヤーの出現地点を描画する。
                if (cell.IsPlayerSpawn)
                {
                    Gizmos.color = Color.blue;

                    Gizmos.DrawSphere(
                        worldPosition,
                        gizmoSize * 2f);
                }

                // 敵の出現地点を描画する。
                if (cell.IsEnemySpawn)
                {
                    Gizmos.color = Color.red;

                    Gizmos.DrawSphere(
                        worldPosition,
                        gizmoSize * 1.8f);
                }

                // 宝石の配置地点を描画する。
                if (cell.HasGem)
                {
                    Gizmos.color = Color.cyan;

                    Gizmos.DrawSphere(
                        worldPosition,
                        gizmoSize * 0.7f);
                }

                // アイテムの配置地点を描画する。
                if (cell.HasItem)
                {
                    Gizmos.color = Color.yellow;

                    Gizmos.DrawCube(
                        worldPosition,
                        Vector3.one * gizmoSize * 2f);
                }

                // アイテムの配置候補地点を描画する。
                if (cell.IsItemSpawn)
                {
                    Gizmos.color = Color.green;

                    Gizmos.DrawWireCube(
                        worldPosition,
                        Vector3.one * gizmoSize * 4f);
                }

                // 破壊可能な壁を描画する。
                if (cell.IsBreakable)
                {
                    Gizmos.color =
                        new Color(1f, 0.5f, 0f);

                    Gizmos.DrawWireCube(
                        worldPosition,
                        Vector3.one * gizmoSize * 5f);
                }
            }
        }

        #endregion

        #region Generation Methods

        /// <summary>
        /// ステージを生成してTilemapへ描画する。
        /// </summary>
        [ContextMenu("テスト/ステージを生成する")]
        public void GenerateStage()
        {
            // 編集モードでの意図しないTilemap変更を防止する。
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードで実行してください。",
                    this);

                return;
            }

            if (!ValidateReferences())
            {
                return;
            }

            // 新しいステージを生成する。
            MazeStageGenerationResult newResult =
                MazeStageGenerator.Generate(settings);

            // 以前の描画システムを解放する。
            ReleaseRenderer();

            // 新しい生成結果を保持する。
            result = newResult;

            // 以前のステージのタイルを消去する。
            floorTilemap.ClearAllTiles();
            wallTilemap.ClearAllTiles();

            // 新しいマップを描画する。
            RenderStage();

            // 生成結果をConsoleへ出力する。
            PrintGenerationResult();

            if (printMap)
            {
                PrintStageMap();
            }

            if (runValidationTests)
            {
                RunValidationTests();
            }
        }

        /// <summary>
        /// 生成済みステージをTilemapへ描画する。
        /// </summary>
        private void RenderStage()
        {
            renderer =
                new GridTilemapRenderer<MazeCell>(
                    result.Map);

            // 床は壁の下を含めて全面に描画する。
            renderer.AddLayer(
                floorTilemap,
                (position, cell) => floorTile);

            // 地形情報に応じて壁タイルを選択する。
            renderer.AddLayer(
                wallTilemap,
                (position, cell) =>
                {
                    if (cell.IsBreakable)
                    {
                        return breakableWallTile != null
                            ? breakableWallTile
                            : wallTile;
                    }

                    return cell.IsWall
                        ? wallTile
                        : null;
                });

            renderer.RenderAll();
        }

        /// <summary>
        /// 現在の描画システムを解放する。
        /// </summary>
        private void ReleaseRenderer()
        {
            if (renderer == null)
            {
                return;
            }

            renderer.Dispose();
            renderer = null;
        }

        #endregion

        #region Validation Tests

        /// <summary>
        /// 生成されたステージの各種条件を検証する。
        /// </summary>
        private void RunValidationTests()
        {
            passedCount = 0;
            failedCount = 0;

            GridMap<MazeCell> map = result.Map;

            // プレイヤー出現地点の数を確認する。
            Check(
                map.CountCells(
                    cell => cell.IsPlayerSpawn) == 1,
                "プレイヤー出現地点が1か所");

            Check(
                map.GetCell(
                    result.PlayerSpawnPosition).IsPlayerSpawn,
                "プレイヤー出現座標とマップ情報の一致");

            // 敵出現地点の数を確認する。
            Check(
                map.CountCells(
                    cell => cell.IsEnemySpawn) ==
                result.EnemySpawnPositions.Count,
                "敵出現地点数とマップ情報の一致");

            Check(
                result.EnemySpawnPositions.Count <=
                settings.EnemyCount,
                "敵の要求配置数を超えていない");

            // アイテム配置候補地点数を確認する。
            Check(
                map.CountCells(
                    cell => cell.IsItemSpawn) ==
                result.ItemSpawnPositions.Count,
                "アイテム配置候補数の一致");

            Check(
                result.InitialItemCount <=
                settings.InitialItemCount,
                "アイテムの要求配置数を超えていない");

            // 宝石の配置数を確認する。
            Check(
                result.InitialGemCount ==
                result.RemainingGemCount,
                "初期宝石数と現在の宝石数の一致");

            Check(
                result.InitialItemCount ==
                result.RemainingItemCount,
                "初期アイテム数と現在の配置数の一致");

            // マスごとの配置ルールを確認する。
            TestCellRules();

            // 敵の出現地点間の距離を確認する。
            TestEnemyDistances();

            // 宝石への到達可能性を確認する。
            TestGemAccessibility();

            // 同一シード値で生成結果を再現できるか確認する。
            TestSeedReproducibility();

            string message =
                "【MazeStageGenerator テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}";

            if (failedCount == 0)
            {
                Debug.Log(
                    message +
                    "\nすべてのテストに成功しました。",
                    this);
            }
            else
            {
                Debug.LogError(message, this);
            }
        }

        /// <summary>
        /// 各マスの配置ルールを検証する。
        /// </summary>
        private void TestCellRules()
        {
            bool validWalls = true;
            bool validCollectibles = true;
            bool validSpawns = true;
            bool validBoundary = true;
            bool validItems = true;

            GridMap<MazeCell> map = result.Map;

            foreach (Vector2Int position in map.GetPositions())
            {
                MazeCell cell = map.GetCell(position);

                // 壁に配置物や出現地点がないことを確認する。
                if (cell.IsWall &&
                    cell.Flags != MazeCellFlags.None)
                {
                    validWalls = false;
                }

                // 宝石とアイテムの重複を確認する。
                if (cell.HasGem && cell.HasItem)
                {
                    validCollectibles = false;
                }

                // 出現地点同士や配置物との重複を確認する。
                if ((cell.IsPlayerSpawn && cell.IsEnemySpawn) ||
                    ((cell.IsPlayerSpawn || cell.IsEnemySpawn) &&
                     cell.HasCollectible))
                {
                    validSpawns = false;
                }

                // アイテムが候補地点に配置されているか確認する。
                if (cell.HasItem && !cell.IsItemSpawn)
                {
                    validItems = false;
                }

                bool isBoundary =
                    position.x == 0 ||
                    position.y == 0 ||
                    position.x == map.Width - 1 ||
                    position.y == map.Height - 1;

                // 外周が通常の壁であることを確認する。
                if (isBoundary &&
                    cell.Terrain != MazeTerrainType.Wall)
                {
                    validBoundary = false;
                }
            }

            Check(validWalls, "壁に配置物が存在しない");

            Check(
                validCollectibles,
                "宝石とアイテムの重複がない");

            Check(
                validSpawns,
                "出現地点の配置ルールを満たしている");

            Check(
                validItems,
                "アイテムが配置候補地点に存在する");

            Check(
                validBoundary,
                "外周が破壊不可能な壁である");
        }

        /// <summary>
        /// プレイヤーと敵、および敵同士の
        /// 最短移動距離を検証する。
        /// </summary>
        private void TestEnemyDistances()
        {
            bool validPlayerDistance = true;
            bool validEnemyDistance = true;

            for (int i = 0;
                 i < result.EnemySpawnPositions.Count;
                 i++)
            {
                Vector2Int enemyPosition =
                    result.EnemySpawnPositions[i];

                int distance =
                    MazeStageGenerator.GetShortestDistance(
                        result.Map,
                        result.PlayerSpawnPosition,
                        enemyPosition);

                if (distance < settings.MinPlayerEnemyDistance)
                {
                    validPlayerDistance = false;
                }

                Debug.Log(
                    $"敵{i + 1}の初期位置：{enemyPosition}\n" +
                    $"プレイヤーからの距離：{distance}",
                    this);

                // 他の敵との距離を確認する。
                for (int j = i + 1;
                     j < result.EnemySpawnPositions.Count;
                     j++)
                {
                    int enemyDistance =
                        MazeStageGenerator.GetShortestDistance(
                            result.Map,
                            enemyPosition,
                            result.EnemySpawnPositions[j]);

                    if (enemyDistance <
                        settings.MinEnemyDistance)
                    {
                        validEnemyDistance = false;
                    }
                }
            }

            Check(
                validPlayerDistance,
                "プレイヤーと敵の距離条件");

            Check(
                validEnemyDistance,
                "敵同士の距離条件");
        }

        /// <summary>
        /// すべての宝石にプレイヤーが到達可能か確認する。
        /// </summary>
        private void TestGemAccessibility()
        {
            bool allAccessible = true;

            foreach (Vector2Int position
                     in result.Map.FindPositions(
                         cell => cell.HasGem))
            {
                int distance =
                    MazeStageGenerator.GetShortestDistance(
                        result.Map,
                        result.PlayerSpawnPosition,
                        position);

                if (distance < 0)
                {
                    allAccessible = false;
                    break;
                }
            }

            Check(
                allAccessible,
                "すべての宝石に到達可能");
        }

        /// <summary>
        /// 同一設定と固定シード値で
        /// 同じステージを再現できるか確認する。
        /// </summary>
        private void TestSeedReproducibility()
        {
            // ランダムシード設定の場合は検証を省略する。
            if (!settings.MazeSettings.UseFixedSeed)
            {
                Debug.Log(
                    "ランダムシードのため再現性テストを省略。",
                    this);

                return;
            }

            MazeStageGenerationResult secondResult =
                MazeStageGenerator.Generate(settings);

            bool isSame =
                result.Width == secondResult.Width &&
                result.Height == secondResult.Height &&
                result.Seed == secondResult.Seed;

            if (isSame)
            {
                foreach (Vector2Int position
                         in result.Map.GetPositions())
                {
                    if (result.Map.GetCell(position) !=
                        secondResult.Map.GetCell(position))
                    {
                        isSame = false;
                        break;
                    }
                }
            }

            Check(
                isSame,
                "固定シードによるステージの再現");
        }

        /// <summary>
        /// テスト結果を記録する。
        /// </summary>
        /// <param name="condition">テストの成功条件</param>
        /// <param name="testName">テスト項目名</param>
        private void Check(
            bool condition,
            string testName)
        {
            if (condition)
            {
                passedCount++;

                Debug.Log(
                    $"[成功] {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"[失敗] {testName}",
                    this);
            }
        }

        /// <summary>
        /// Inspectorで必要な参照が設定されているか確認する。
        /// </summary>
        /// <returns>必要な参照が有効な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (coordinateConverter == null ||
                floorTilemap == null ||
                wallTilemap == null ||
                floorTile == null ||
                wallTile == null)
            {
                Debug.LogError(
                    "必要な参照が設定されていません。",
                    this);

                return false;
            }

            if (floorTilemap == wallTilemap)
            {
                Debug.LogError(
                    "床と壁には別々のTilemapを設定してください。",
                    this);

                return false;
            }

            return true;
        }

        #endregion

        #region Debug Methods

        /// <summary>
        /// ステージ生成結果をConsoleへ出力する。
        /// </summary>
        private void PrintGenerationResult()
        {
            Debug.Log(
                "【ステージ生成結果】\n" +
                $"シード値：{result.Seed}\n" +
                $"サイズ：{result.Width} × {result.Height}\n" +
                $"プレイヤー位置：{result.PlayerSpawnPosition}\n" +
                $"敵出現地点数：{result.EnemySpawnPositions.Count}\n" +
                $"宝石数：{result.InitialGemCount}\n" +
                $"アイテム数：{result.InitialItemCount}\n" +
                $"アイテム候補数：{result.ItemSpawnPositions.Count}\n" +
                $"破壊可能な壁数：{result.InitialBreakableWallCount}",
                this);

            if (result.EnemySpawnPositions.Count <
                settings.EnemyCount)
            {
                Debug.LogWarning(
                    "距離条件を満たす敵出現地点が不足しています。",
                    this);
            }

            if (result.InitialItemCount <
                settings.InitialItemCount)
            {
                Debug.LogWarning(
                    "アイテムの配置可能地点が不足しています。",
                    this);
            }

            if (result.ItemSpawnPositions.Count <
                Mathf.Max(
                    settings.ItemSpawnCount,
                    settings.InitialItemCount))
            {
                Debug.LogWarning(
                    "アイテム配置候補地点が不足しています。",
                    this);
            }

            if (result.InitialGemCount == 0)
            {
                Debug.LogWarning(
                    "宝石が配置されていません。",
                    this);
            }
        }

        /// <summary>
        /// 生成されたマップを文字列としてConsoleへ出力する。
        /// </summary>
        private void PrintStageMap()
        {
            System.Text.StringBuilder builder =
                new System.Text.StringBuilder();

            builder.AppendLine("【生成ステージ】");

            // UnityのY座標に合わせて上から下へ出力する。
            for (int y = result.Height - 1; y >= 0; y--)
            {
                for (int x = 0; x < result.Width; x++)
                {
                    MazeCell cell =
                        result.Map.GetCell(x, y);

                    builder.Append(
                        GetCellCharacter(cell));
                }

                builder.AppendLine();
            }

            builder.AppendLine(
                "#：壁  X：破壊可能な壁  P：プレイヤー");

            builder.AppendLine(
                "E：敵  G：宝石  I：アイテム");

            builder.AppendLine(
                "S：アイテム候補  .：床");

            Debug.Log(builder.ToString(), this);
        }

        /// <summary>
        /// マスデータをデバッグ表示用の文字へ変換する。
        /// </summary>
        /// <param name="cell">変換対象のマス</param>
        /// <returns>マスの状態を表す文字</returns>
        private char GetCellCharacter(MazeCell cell)
        {
            if (cell.IsBreakable) return 'X';
            if (cell.IsWall) return '#';
            if (cell.IsPlayerSpawn) return 'P';
            if (cell.IsEnemySpawn) return 'E';
            if (cell.HasItem) return 'I';
            if (cell.HasGem) return 'G';
            if (cell.IsItemSpawn) return 'S';

            return '.';
        }

        #endregion
    }
}
